 IF EXISTS(SELECT 1 FROM bill2_runs WHERE id=p_run_id AND actor_id=p_actor_id AND contract_version='bill2.v2') THEN RETURN bill2_payg_claim(p_actor_id,p_run_id,p_sequence,p_payload); END IF;
